INSERT INTO `reason` VALUES (1, 'ปัญหาการจราจร เช่น ฝนตก รถติด', 'รวมกรณีฝนตก รถติด และการจราจรล่าช้า', 1, 20);
INSERT INTO `reason` VALUES (2, 'ปัญหาด้านสุขภาพ เช่น ท้องเสีย ปวดหัว', 'รวมอาการเจ็บป่วยหรือสุขภาพไม่พร้อม', 1, 50);
INSERT INTO `reason` VALUES (3, 'จำเวลาสอบผิด', 'คลาดเคลื่อนเรื่องวันหรือเวลาสอบ', 1, 70);
INSERT INTO `reason` VALUES (4, 'อื่น ๆ', 'โปรดระบุรายละเอียดเพิ่มเติม', 1, 100);
INSERT INTO `reason` VALUES (5, 'เหตุสุดวิสัยอื่น', 'ข้อมูลเดิม — ไม่แสดงในฟอร์มบันทึกใหม่', 0, 900);
INSERT INTO `reason` VALUES (6, 'ลืมอุปกรณ์ที่ใช้ในการสอบ', 'ลืมพกเอกสารหรืออุปกรณ์ที่ใช้ในการสอบ', 1, 60);
INSERT INTO `reason` VALUES (7, 'อุปสรรคในการเดินทาง เช่น รถเสีย ยางแบน น้ำมันหมด', 'รวมรถเสีย ยางแบน น้ำมันหมด หรืออุปสรรคเดินทางอื่น', 1, 30);
INSERT INTO `reason` VALUES (8, 'อื่น ๆ (ข้อมูลเดิม)', 'ข้อมูลเดิม — ไม่แสดงในฟอร์มบันทึกใหม่', 0, 910);
INSERT INTO `reason` VALUES (9, 'แต่งกายผิดระเบียบ กลับไปแต่งตัวให้เรียบร้อย', 'แต่งกายไม่ถูกต้องตามระเบียบการสอบ', 1, 10);
INSERT INTO `reason` VALUES (10, 'ตื่นสาย', 'ตื่นสายทำให้มาสอบไม่ทันเวลา', 1, 40);
